SAVEPOINT A;
UPDATE ACC SET BAL = BAL + 30 WHERE ID = 2;
SAVEPOINT B;
DELETE FROM ACC WHERE ID = 2;
ROLLBACK TO SAVEPOINT B;
UPDATE ACC SET BAL = BAL + 10 WHERE ID = 1;
ROLLBACK TO SAVEPOINT A;
COMMIT;
SELECT (SELECT BAL FROM ACC WHERE ID = 1) AS BAL1,
       (SELECT BAL FROM ACC WHERE ID = 2) AS BAL2
  FROM DUAL;

